<?php declare(strict_types=1); namespace Haerriz\AgenticCommerce\Model\Tool;
use Haerriz\AgenticCommerce\Model\Wishlist\WishlistService; use Magento\Framework\Exception\LocalizedException;
class AddRecentProductToWishlist implements ToolInterface { public function __construct(private WishlistService $service){} public function getName():string{return 'add_recent_product_to_wishlist';} public function getDefinition():array{return ['type'=>'function','function'=>['name'=>$this->getName(),'description'=>'Save a product from the server-owned recent results by 1-based position.','parameters'=>['type'=>'object','properties'=>['index'=>['type'=>'integer','minimum'=>1]],'required'=>['index']]]];} public function execute(array $arguments,array $context=[]):array{$i=(int)($arguments['index']??0);$r=(array)($context['recent_products']??[]);if($i<1||!isset($r[$i-1]['sku']))throw new LocalizedException(__('That product is no longer available in the recent result context.'));return $this->service->add((array)($context['identity']??[]),(string)$r[$i-1]['sku']);} }
